import{_ as s,I as o,o as g,c as h,b6 as d,J as r}from"./chunks/framework.COUcLbTA.js";const P=JSON.parse('{"title":"模型微调与部署","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/appendix/8-artificial-intelligence/model-finetuning-deployment.md","filePath":"zh-cn/appendix/8-artificial-intelligence/model-finetuning-deployment.md"}'),p={name:"zh-cn/appendix/8-artificial-intelligence/model-finetuning-deployment.md"};function _(c,t,u,b,m,T){const n=o("FinetuningPipelineDemo"),l=o("TrainingDataDemo"),e=o("LoRADemo"),i=o("ModelQuantizationDemo"),a=o("ModelServingDemo");return g(),h("div",null,[t[0]||(t[0]=d('<h1 id="模型微调与部署" tabindex="-1">模型微调与部署 <a class="header-anchor" href="#模型微调与部署" aria-label="Permalink to “模型微调与部署”">​</a></h1><div class="tip custom-block"><p class="custom-block-title">前言</p><p><strong>大模型很强，但它不懂你的业务。</strong> GPT-4 能写诗、能编程，但它不知道你公司的产品术语、不了解你行业的专业规范。微调（Fine-tuning）就是让通用大模型&quot;学会&quot;你的专业知识的过程——就像给一个博学的通才做岗前培训，让它变成你的领域专家。</p></div><p><strong>这篇文章会带你学什么？</strong></p><p>学完这章后，你将获得：</p><ul><li><strong>流程认知</strong>：掌握从数据准备到模型上线的完整微调流水线</li><li><strong>数据工程</strong>：了解微调数据的格式要求和质量标准</li><li><strong>高效微调</strong>：理解 LoRA 等参数高效微调技术的原理和优势</li><li><strong>模型压缩</strong>：掌握量化技术如何让大模型在消费级硬件上运行</li><li><strong>部署实践</strong>：了解模型服务的主流架构和选型策略</li></ul><table tabindex="0"><thead><tr><th>章节</th><th>内容</th><th>核心概念</th></tr></thead><tbody><tr><td><strong>第 1 章</strong></td><td>微调流水线</td><td>数据→训练→评估→部署</td></tr><tr><td><strong>第 2 章</strong></td><td>训练数据</td><td>数据格式、质量控制</td></tr><tr><td><strong>第 3 章</strong></td><td>LoRA 微调</td><td>低秩适配、参数高效</td></tr><tr><td><strong>第 4 章</strong></td><td>模型量化</td><td>FP16、INT8、INT4</td></tr><tr><td><strong>第 5 章</strong></td><td>模型部署</td><td>推理服务、API 网关</td></tr></tbody></table><hr><h2 id="_0-全景图-为什么需要微调" tabindex="-1">0. 全景图：为什么需要微调？ <a class="header-anchor" href="#_0-全景图-为什么需要微调" aria-label="Permalink to “0. 全景图：为什么需要微调？”">​</a></h2><p>大语言模型的训练分为两个阶段：<strong>预训练</strong>和<strong>微调</strong>。预训练是在海量通用数据上学习语言能力，微调是在特定任务数据上学习专业能力。</p><p>打个比方：预训练像是上大学——学习通识知识，什么都懂一点；微调像是入职培训——针对具体岗位学习专业技能。</p><div class="tip custom-block"><p class="custom-block-title">什么时候需要微调？</p><ul><li><strong>特定输出格式</strong>：需要模型始终以固定 JSON 格式输出</li><li><strong>专业领域知识</strong>：医疗、法律、金融等领域的专业术语和规范</li><li><strong>语言风格迁移</strong>：让模型用特定的语气、风格回答（如客服话术）</li><li><strong>小众语言支持</strong>：提升模型在特定语言上的表现</li><li><strong>成本优化</strong>：用小模型微调替代大模型调用，降低推理成本</li></ul></div><hr><h2 id="_1-微调流水线-从数据到上线的完整旅程" tabindex="-1">1. 微调流水线：从数据到上线的完整旅程 <a class="header-anchor" href="#_1-微调流水线-从数据到上线的完整旅程" aria-label="Permalink to “1. 微调流水线：从数据到上线的完整旅程”">​</a></h2><p>微调不是&quot;把数据丢给模型就完事&quot;。它是一个严谨的工程流程，每个环节都会影响最终效果。</p>',14)),r(n),t[1]||(t[1]=d('<div class="tip custom-block"><p class="custom-block-title">微调的五个阶段</p><ol><li><strong>数据准备</strong>：收集、清洗、标注训练数据，这是最耗时也最关键的环节</li><li><strong>模型选择</strong>：选择合适的基座模型（Base Model），如 Llama 3、Qwen、Mistral</li><li><strong>训练配置</strong>：设置学习率、batch size、epoch 数等超参数</li><li><strong>训练执行</strong>：在 GPU 上运行训练，监控 loss 曲线和评估指标</li><li><strong>评估上线</strong>：在测试集上评估效果，通过后部署为 API 服务</li></ol></div><table tabindex="0"><thead><tr><th>阶段</th><th>关键动作</th><th>常见陷阱</th></tr></thead><tbody><tr><td>数据准备</td><td>清洗、去重、格式化</td><td>数据质量差导致模型&quot;学坏&quot;</td></tr><tr><td>模型选择</td><td>评估基座模型能力</td><td>模型太大训练不动，太小效果差</td></tr><tr><td>训练配置</td><td>调整超参数</td><td>学习率过高导致灾难性遗忘</td></tr><tr><td>训练执行</td><td>监控 loss 和指标</td><td>过拟合、训练不收敛</td></tr><tr><td>评估上线</td><td>A/B 测试、灰度发布</td><td>测试集泄漏导致评估虚高</td></tr></tbody></table><hr><h2 id="_2-训练数据-微调效果的天花板" tabindex="-1">2. 训练数据：微调效果的天花板 <a class="header-anchor" href="#_2-训练数据-微调效果的天花板" aria-label="Permalink to “2. 训练数据：微调效果的天花板”">​</a></h2><p>在微调中有一句老话：<strong>&quot;Garbage in, garbage out&quot;</strong>。训练数据的质量直接决定了微调效果的上限。100 条高质量数据的效果，往往好过 10000 条低质量数据。</p>',5)),r(l),t[2]||(t[2]=d('<div class="tip custom-block"><p class="custom-block-title">微调数据的三种常见格式</p><ol><li><strong>指令格式（Instruction）</strong>：最常用的格式，包含 instruction（指令）、input（输入）、output（期望输出）三个字段。适合训练模型遵循指令。</li><li><strong>对话格式（Chat）</strong>：多轮对话形式，包含 system、user、assistant 角色的消息列表。适合训练聊天机器人。</li><li><strong>补全格式（Completion）</strong>：简单的 prompt-completion 对，适合文本生成、代码补全等场景。</li></ol></div><table tabindex="0"><thead><tr><th>数据质量维度</th><th>说明</th><th>检查方法</th></tr></thead><tbody><tr><td>准确性</td><td>答案必须正确无误</td><td>人工审核、专家校验</td></tr><tr><td>一致性</td><td>相似问题的回答风格一致</td><td>抽样对比检查</td></tr><tr><td>多样性</td><td>覆盖足够多的场景和变体</td><td>统计问题类型分布</td></tr><tr><td>去重</td><td>避免重复样本导致过拟合</td><td>文本去重、语义去重</td></tr><tr><td>数据量</td><td>通常 500~5000 条高质量数据即可</td><td>从少量开始，逐步增加</td></tr></tbody></table><hr><h2 id="_3-lora-用-1-的参数实现-90-的效果" tabindex="-1">3. LoRA：用 1% 的参数实现 90% 的效果 <a class="header-anchor" href="#_3-lora-用-1-的参数实现-90-的效果" aria-label="Permalink to “3. LoRA：用 1% 的参数实现 90% 的效果”">​</a></h2><p>全量微调（Full Fine-tuning）需要更新模型的所有参数——对于一个 70B 参数的模型，这意味着需要数百 GB 的显存和大量的 GPU 算力。对大多数团队来说，这不现实。</p><p>LoRA（Low-Rank Adaptation）提供了一个优雅的解决方案：<strong>冻结原始模型参数，只训练一小组新增的低秩矩阵</strong>。这些矩阵的参数量通常只有原模型的 0.1%~1%，但能达到接近全量微调的效果。</p>',6)),r(e),t[3]||(t[3]=d('<div class="tip custom-block"><p class="custom-block-title">LoRA 的核心思想</p><p>原始模型的权重矩阵 W 是一个巨大的矩阵（如 4096×4096）。LoRA 不直接修改 W，而是在旁边加一个&quot;旁路&quot;：W&#39; = W + BA，其中 B 和 A 是两个小矩阵（如 4096×8 和 8×4096）。训练时只更新 B 和 A，原始 W 保持不变。</p><ul><li><strong>秩（Rank）</strong>：r 值越大，表达能力越强，但参数量也越多。通常 r=8~64 就够用</li><li><strong>合并部署</strong>：训练完成后，可以把 BA 合并回 W，推理时零额外开销</li></ul></div><table tabindex="0"><thead><tr><th>微调方式</th><th>可训练参数</th><th>显存需求</th><th>训练速度</th><th>效果</th></tr></thead><tbody><tr><td>全量微调</td><td>100%</td><td>极高</td><td>慢</td><td>最好</td></tr><tr><td>LoRA</td><td>0.1%~1%</td><td>低</td><td>快</td><td>接近全量</td></tr><tr><td>QLoRA</td><td>0.1%~1%</td><td>更低</td><td>中等</td><td>略低于 LoRA</td></tr><tr><td>Prompt Tuning</td><td>&lt; 0.01%</td><td>极低</td><td>很快</td><td>有限</td></tr></tbody></table><hr><h2 id="_4-模型量化-让大模型-瘦身" tabindex="-1">4. 模型量化：让大模型&quot;瘦身&quot; <a class="header-anchor" href="#_4-模型量化-让大模型-瘦身" aria-label="Permalink to “4. 模型量化：让大模型&quot;瘦身&quot;”">​</a></h2><p>一个 70B 参数的模型，如果用 FP32（32 位浮点数）存储，需要 280GB 显存——没有几块顶级 GPU 根本跑不起来。量化（Quantization）技术通过降低数值精度来压缩模型体积，让大模型能在消费级硬件上运行。</p>',5)),r(i),t[4]||(t[4]=d('<div class="tip custom-block"><p class="custom-block-title">量化的核心权衡</p><p>量化本质上是<strong>精度换空间</strong>的权衡。FP32 → FP16 几乎无损，INT8 有轻微损失，INT4 会有明显但通常可接受的质量下降。关键是找到你场景下的最佳平衡点。</p><ul><li><strong>FP16（半精度）</strong>：体积减半，质量几乎无损，是训练和推理的默认选择</li><li><strong>INT8（8 位整数）</strong>：体积再减半，质量损失很小，适合大多数推理场景</li><li><strong>INT4（4 位整数）</strong>：体积仅为 FP32 的 1/8，质量有一定损失，适合资源受限场景</li></ul></div><table tabindex="0"><thead><tr><th>精度</th><th>每参数字节</th><th>70B 模型体积</th><th>质量损失</th><th>适用场景</th></tr></thead><tbody><tr><td>FP32</td><td>4 字节</td><td>~280 GB</td><td>无</td><td>训练基准</td></tr><tr><td>FP16</td><td>2 字节</td><td>~140 GB</td><td>几乎无</td><td>标准训练和推理</td></tr><tr><td>INT8</td><td>1 字节</td><td>~70 GB</td><td>很小</td><td>生产推理</td></tr><tr><td>INT4</td><td>0.5 字节</td><td>~35 GB</td><td>可接受</td><td>边缘设备、本地部署</td></tr></tbody></table><hr><h2 id="_5-模型部署-从实验室到生产环境" tabindex="-1">5. 模型部署：从实验室到生产环境 <a class="header-anchor" href="#_5-模型部署-从实验室到生产环境" aria-label="Permalink to “5. 模型部署：从实验室到生产环境”">​</a></h2><p>模型训练好了，量化压缩了，最后一步是把它部署成可供调用的服务。模型部署不只是&quot;把模型跑起来&quot;，还涉及并发处理、负载均衡、成本控制等工程问题。</p>',5)),r(a),t[5]||(t[5]=d('<div class="tip custom-block"><p class="custom-block-title">三种主流部署方案</p><ol><li><strong>API 服务商</strong>：直接使用 OpenAI、Anthropic 等厂商的 API。零运维，按 token 付费，适合快速验证和中小规模使用。</li><li><strong>自托管推理服务</strong>：用 vLLM、TGI 等框架在自己的 GPU 服务器上部署。成本可控，数据不出域，适合有隐私要求或大规模调用的场景。</li><li><strong>Serverless 推理</strong>：使用 AWS SageMaker、Replicate 等平台，按请求付费，自动扩缩容。适合流量波动大的场景。</li></ol></div><table tabindex="0"><thead><tr><th>部署方案</th><th>成本模型</th><th>延迟</th><th>运维复杂度</th><th>适用场景</th></tr></thead><tbody><tr><td>API 服务商</td><td>按 token 计费</td><td>中等</td><td>零</td><td>快速原型、中小规模</td></tr><tr><td>vLLM 自部署</td><td>GPU 租赁费用</td><td>低</td><td>高</td><td>大规模、隐私敏感</td></tr><tr><td>Serverless</td><td>按请求计费</td><td>冷启动较高</td><td>低</td><td>流量波动大</td></tr><tr><td>边缘部署</td><td>硬件一次性投入</td><td>极低</td><td>中</td><td>离线场景、IoT</td></tr></tbody></table><hr><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h2><p>模型微调与部署是让大模型从&quot;通用工具&quot;变成&quot;专业助手&quot;的关键环节。从数据准备到模型上线，每一步都需要工程化的思维和实践。</p><p>回顾本章的关键要点：</p><ol><li><strong>微调是岗前培训</strong>：让通用模型学会特定领域的知识和行为模式</li><li><strong>数据质量决定上限</strong>：100 条高质量数据胜过 10000 条低质量数据</li><li><strong>LoRA 是效率之王</strong>：用不到 1% 的参数实现接近全量微调的效果</li><li><strong>量化是部署利器</strong>：INT4 量化让 70B 模型在单卡上运行成为可能</li><li><strong>部署方案因地制宜</strong>：快速验证用 API，大规模用自部署，波动大用 Serverless</li></ol><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to “延伸阅读”">​</a></h2><ul><li><a href="https://huggingface.co/docs/peft" target="_blank" rel="noreferrer">Hugging Face PEFT 文档</a> - 参数高效微调库官方文档</li><li><a href="https://docs.vllm.ai/" target="_blank" rel="noreferrer">vLLM 文档</a> - 高性能 LLM 推理引擎</li><li><a href="https://github.com/unslothai/unsloth" target="_blank" rel="noreferrer">Unsloth</a> - 2x 加速的 LoRA 微调框架</li><li><a href="https://github.com/ggerganov/ggml/blob/master/docs/gguf.md" target="_blank" rel="noreferrer">GGUF 格式说明</a> - llama.cpp 使用的量化模型格式</li><li><a href="https://platform.openai.com/docs/guides/fine-tuning" target="_blank" rel="noreferrer">OpenAI Fine-tuning Guide</a> - OpenAI 官方微调指南</li></ul>',9))])}const f=s(p,[["render",_]]);export{P as __pageData,f as default};
